INSERT INTO especialidades
  (slug, nombre, ciclo, duracion, duracion_corta, color, descripcion_corta, descripcion, requisitos, turnos, icono_svg, estado, orden)
VALUES
('gastronomia', 'Servicio Básico Gastronómico', 'auxiliar', '1 Año de estudio', '1 Año', '#B84E0C', 'Prepara platillos, maneja cocina profesional y brinda atención de calidad en restaurantes y servicios alimentarios.', 'Aprenderás técnicas profesionales de preparación de alimentos, gestión de cocina, manipulación higiénica de alimentos y atención al cliente en establecimientos gastronómicos. Perfecto para emprender tu propio negocio o trabajar en restaurantes y hoteles.', '["Certificado de estudios primarios o secundarios","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Certificado de salud (se tramita en el CESAMICA)","Tener entre 15 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <path d="M12 8v14a10 10 0 0020 0V8" stroke="#B84E0C" stroke-width="2.5" stroke-linecap="round"/> <line x1="22" y1="8" x2="22" y2="26" stroke="#B84E0C" stroke-width="2.5" stroke-linecap="round"/> <line x1="32" y1="8" x2="32" y2="40" stroke="#B84E0C" stroke-width="2.5" stroke-linecap="round"/> <line x1="8" y1="40" x2="40" y2="40" stroke="#B84E0C" stroke-width="2.5" stroke-linecap="round"/> </svg>', 'publicado', 1),
('panaderia', 'Panadería', 'auxiliar', '1 Año de estudio', '1 Año', '#9A6A00', 'Domina técnicas de panadería artesanal, pastelería básica y producción de panes tradicionales ayacuchanos y modernos.', 'Domina técnicas de panadería artesanal e industrial, pastelería básica y producción de panes tradicionales ayacuchanos y modernos. Desarrolla las habilidades para abrir tu propia panadería o trabajar en la industria alimentaria.', '["Certificado de estudios primarios completos","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Certificado de salud actualizado","Tener entre 15 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <ellipse cx="24" cy="28" rx="16" ry="10" stroke="#9A6A00" stroke-width="2.5"/> <path d="M8 28 Q24 10 40 28" stroke="#9A6A00" stroke-width="2.5" stroke-linecap="round" fill="none"/> <path d="M16 24 Q24 18 32 24" stroke="#9A6A00" stroke-width="2" stroke-linecap="round" fill="none" opacity="0.6"/> <circle cx="24" cy="20" r="3" fill="#9A6A00" opacity="0.4"/> </svg>', 'publicado', 2),
('adultomayor', 'Cuidado del Adulto Mayor', 'auxiliar', '1 Año de estudio', '1 Año', '#C0262D', 'Brinda cuidados básicos de salud, asistencia personal y actividades de bienestar para el adulto mayor con calidez y profesionalismo.', 'Adquiere las competencias para brindar cuidados básicos de salud, asistencia personal, movilización segura y actividades de bienestar y recreación para adultos mayores. Carrera con alta demanda en hogares, centros de reposo y servicios de salud.', '["Secundaria completa (obligatorio)","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Certificado de salud y de buena conducta","Tener entre 18 y 55 años de edad"]', '["Mañana (7:30 – 12:30)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <circle cx="24" cy="13" r="7" stroke="#C0262D" stroke-width="2.5"/> <path d="M10 40c0-7.73 6.27-14 14-14s14 6.27 14 14" stroke="#C0262D" stroke-width="2.5" stroke-linecap="round"/> <path d="M24 30 l-4 4 6 6 8-10" stroke="#C0262D" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/> </svg>', 'publicado', 3),
('casas', 'Mantenimiento de Casas', 'auxiliar', '1 Año de estudio', '1 Año', '#0A6C9E', 'Aprende plomería básica, instalaciones eléctricas domiciliarias, pintura y carpintería para el mantenimiento del hogar.', 'Aprende plomería básica, instalaciones eléctricas domiciliarias seguras, pintura de interiores y exteriores, y carpintería básica. Una formación práctica para trabajar de forma independiente o en empresas de construcción y mantenimiento.', '["Certificado de estudios primarios","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Tener entre 15 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <path d="M6 22L24 6l18 16" stroke="#0A6C9E" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/> <rect x="14" y="22" width="20" height="18" rx="2" stroke="#0A6C9E" stroke-width="2.5"/> <path d="M32 32 l6-6 m0 6 l-6-6" stroke="#0A6C9E" stroke-width="2" stroke-linecap="round"/> <circle cx="32" cy="29" r="5" stroke="#0A6C9E" stroke-width="2" opacity="0.7"/> </svg>', 'publicado', 4),
('estilismo', 'Estilismo', 'tecnico', '2 Años de estudio', '2 Años', '#1A7F26', 'Corte, peinado, coloración y tratamientos capilares profesionales para damas y caballeros. ¡Crea tu propio negocio!', 'Formación completa en corte de cabello, peinados, coloración, tratamientos capilares, manicura y pedicura para damas y caballeros. Al egresar tendrás las herramientas para abrir tu propio salón de belleza o trabajar en centros estéticos reconocidos.', '["Secundaria completa (obligatorio)","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Certificado de salud actualizado","Tener entre 16 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <circle cx="17" cy="17" r="7" stroke="#1A7F26" stroke-width="2.5"/> <circle cx="31" cy="17" r="7" stroke="#1A7F26" stroke-width="2.5"/> <line x1="24" y1="17" x2="24" y2="42" stroke="#1A7F26" stroke-width="2.5" stroke-linecap="round"/> <line x1="17" y1="24" x2="31" y2="24" stroke="#1A7F26" stroke-width="2" stroke-linecap="round" opacity="0.6"/> </svg>', 'publicado', 5),
('electronico', 'Mantenimiento Electrónico', 'tecnico', '2 Años de estudio', '2 Años', '#0A5F8C', 'Repara equipos electrónicos, celulares y electrodomésticos. Alta demanda laboral en Ayacucho y todo el Perú.', 'Aprende a diagnosticar y reparar equipos electrónicos: televisores, equipos de sonido, celulares y electrodomésticos. Incluye soldadura, lectura de circuitos y gestión de taller. Alta demanda laboral en Ayacucho y a nivel nacional.', '["Secundaria completa (obligatorio)","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Tener entre 16 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <rect x="8" y="16" width="32" height="20" rx="3" stroke="#0A5F8C" stroke-width="2.5"/> <line x1="18" y1="36" x2="16" y2="42" stroke="#0A5F8C" stroke-width="2.5" stroke-linecap="round"/> <line x1="30" y1="36" x2="32" y2="42" stroke="#0A5F8C" stroke-width="2.5" stroke-linecap="round"/> <line x1="12" y1="42" x2="36" y2="42" stroke="#0A5F8C" stroke-width="2.5" stroke-linecap="round"/> <path d="M20 22 l3 3 6-7" stroke="#0A5F8C" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> <circle cx="36" cy="10" r="4" fill="#0A5F8C" opacity="0.3" stroke="#0A5F8C" stroke-width="2"/> <line x1="36" y1="6" x2="36" y2="4" stroke="#0A5F8C" stroke-width="1.5" stroke-linecap="round"/> <line x1="39" y1="7" x2="41" y2="5" stroke="#0A5F8C" stroke-width="1.5" stroke-linecap="round"/> <line x1="40" y1="10" x2="42" y2="10" stroke="#0A5F8C" stroke-width="1.5" stroke-linecap="round"/> </svg>', 'publicado', 6),
('confeccion', 'Confección de Prendas', 'tecnico', '2 Años de estudio', '2 Años', '#B84E0C', 'Diseña, corta y confecciona prendas de vestir con máquinas industriales. Emprende tu taller o trabaja en la industria textil.', 'Diseña, traza, corta y confecciona prendas de vestir utilizando máquinas industriales de coser y overlook. Aprende patronaje, transformaciones y escalado. Ideal para emprender tu propio taller o insertarte en la industria textil local.', '["Certificado de estudios primarios completos","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Tener entre 15 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <path d="M16 8 L10 20 L18 20 L18 40 L30 40 L30 20 L38 20 L32 8" stroke="#B84E0C" stroke-width="2.5" stroke-linejoin="round"/> <line x1="16" y1="8" x2="32" y2="8" stroke="#B84E0C" stroke-width="2.5" stroke-linecap="round"/> <path d="M22 14 Q24 12 26 14" stroke="#B84E0C" stroke-width="2" stroke-linecap="round" fill="none"/> <circle cx="24" cy="14" r="2" fill="#B84E0C" opacity="0.5"/> </svg>', 'publicado', 7),
('soporte', 'Soporte Técnico', 'tecnico', '2 Años de estudio', '2 Años', '#0A6C9E', 'Mantenimiento de PCs, instalación de software, redes básicas y soporte a usuarios. Carrera con alta empleabilidad.', 'Formación en mantenimiento preventivo y correctivo de computadoras, instalación de sistemas operativos y software, configuración de redes básicas y soporte a usuarios. Una de las carreras con mayor empleabilidad en el sector público y privado.', '["Secundaria completa (obligatorio)","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Conocimientos básicos de computadora (deseable)","Tener entre 16 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <rect x="6" y="10" width="36" height="24" rx="3" stroke="#0A6C9E" stroke-width="2.5"/> <line x1="16" y1="38" x2="32" y2="38" stroke="#0A6C9E" stroke-width="2.5" stroke-linecap="round"/> <line x1="24" y1="34" x2="24" y2="38" stroke="#0A6C9E" stroke-width="2.5" stroke-linecap="round"/> <path d="M18 22 h4 l2-5 3 10 2-5 h5" stroke="#0A6C9E" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/> </svg>', 'publicado', 8),
('administrativo', 'Apoyo Administrativo', 'tecnico', '2 Años de estudio', '2 Años', '#1A7F26', 'Contabilidad básica, gestión documental, digitación y atención al cliente. Indispensable en toda empresa u oficina pública.', 'Capacitación en contabilidad básica, gestión y organización documental, digitación avanzada, atención al cliente y manejo de software de oficina (Word, Excel). Indispensable en toda empresa, municipalidad u oficina pública de Ayacucho.', '["Secundaria completa (obligatorio)","Copia del Documento Nacional de Identidad (DNI)","2 fotografías tamaño carné (fondo blanco)","Tener entre 16 y 55 años de edad"]', '["Mañana (7:30 – 12:30)","Tarde (14:00 – 18:45)"]', '<svg viewBox="0 0 48 48" fill="none" aria-hidden="true"> <rect x="10" y="6" width="28" height="36" rx="3" stroke="#1A7F26" stroke-width="2.5"/> <line x1="16" y1="16" x2="32" y2="16" stroke="#1A7F26" stroke-width="2" stroke-linecap="round"/> <line x1="16" y1="22" x2="32" y2="22" stroke="#1A7F26" stroke-width="2" stroke-linecap="round"/> <line x1="16" y1="28" x2="26" y2="28" stroke="#1A7F26" stroke-width="2" stroke-linecap="round"/> <circle cx="34" cy="36" r="6" fill="white" stroke="#1A7F26" stroke-width="2"/> <path d="M31 36 l2 2 4-4" stroke="#1A7F26" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/> </svg>', 'publicado', 9);
